  const {error}=await supabase.from('salon_appointments').insert({org_id:currentOrg.id,customer_id:customer.id,customer_name:values.customer_name.trim(),customer_phone:values.customer_phone.trim(),customer_email:values.customer_email?.trim()||null,service_id:service.id,service_name:service.name,staff_id:staff?.id||null,staff_name:staff?.name||null,starts_at:starts.toISOString(),ends_at:ends.toISOString(),price:values.price===''?Number(service.price||0):Number(values.price),notes:values.notes?.trim()||null,source:'admin',reminder_status:'pending',created_by:session.user.id});
  if(error){toast(error.message);return false}await loadWorkspaceData();render('salon');toast('Appointment booked and added to the reminder queue');return true;
