  $$('[data-appointment-checkout]',page).forEach(b=>b.onclick=()=>{const appointment=salonAppointments.find(item=>item.id===b.dataset.appointmentCheckout);if(!appointment)return;const service=salonServices.find(item=>item.id===appointment.service_id);if(!service)return toast('The linked service is no longer available');posSelectedCustomer=retailCustomers.find(item=>item.id===appointment.customer_id)||retailCustomers.find(item=>item.phone_normalized===appointment.customer_phone)||null;posAppointmentId=appointment.id;const serviceLine={id:`service:${service.id}`,serviceId:service.id,itemType:'service',name:service.name,sku:`SERVICE · ${service.duration_minutes} min`,category:'Salon services',stock:null,cost:0,price:Number(appointment.price??service.price??0),duration:Number(service.duration_minutes),appointmentId:appointment.id,quantity:1};posCart=[serviceLine,...posCart.filter(item=>item.itemType==='product')];render('pos');toast('Client and booked service loaded into checkout')});
  $$('[data-appointment-advance]',page).forEach(b=>b.onclick=async()=>{const appointment=salonAppointments.find(a=>a.id===b.dataset.appointmentAdvance);if(!appointment||['completed','cancelled','no_show'].includes(appointment.status))return toast('Appointment details opened');const next={booked:'confirmed',confirmed:'in_service',in_service:'completed'}[appointment.status];const {error}=await supabase.from('salon_appointments').update({status:next}).eq('id',appointment.id);if(error)return toast(error.message);await loadWorkspaceData();render('salon');toast(`Appointment moved to ${next.replace('_',' ')}`)});
