 const all=Object.entries(appGroups).flatMap(([g,items])=>items.map(i=>({name:i,meta:g,route:({Sales:'sales',Finance:'finance',Operations:'inventory',People:'people',Marketing:'marketing',Services:'services',Productivity:'productivity',Website:'commerce'})[g]})));
