async function loadWorkspaceData(){
  const profileResult=await supabase.from('profiles').select('*').eq('id',session.user.id).single();
  if(profileResult.error)throw profileResult.error;
  userProfile=profileResult.data;
  const membershipResult=await supabase.from('memberships').select('org_id,role,status,organizations(*)').eq('user_id',session.user.id).eq('status','active').limit(1).single();
  if(membershipResult.error)throw membershipResult.error;
  currentMembership=membershipResult.data;
  currentOrg=membershipResult.data.organizations;
  canManagePayroll=userProfile.platform_role==='super_admin'||['owner','admin','manager'].includes(currentMembership.role);
  const [settingsResult,dealsResult,invoicesResult,productsResult,employeesResult,projectsResult,customersResult,posOrdersResult,compensationResult,payrollResult,prescriptionsResult,batchesResult,appointmentsResult,servicesResult,jobsResult,vehiclesResult,availabilityResult]=await Promise.all([
    supabase.from('organization_settings').select('*').eq('org_id',currentOrg.id).single(),
    supabase.from('opportunities').select('*').eq('org_id',currentOrg.id).order('created_at',{ascending:false}),
    supabase.from('invoices').select('*').eq('org_id',currentOrg.id).order('created_at',{ascending:false}),
    supabase.from('products').select('*').eq('org_id',currentOrg.id).eq('active',true).order('name'),
    supabase.from('employees').select('*').eq('org_id',currentOrg.id).order('name'),
    supabase.from('projects').select('*').eq('org_id',currentOrg.id).order('created_at',{ascending:false}),
    supabase.from('retail_customers').select('*').eq('org_id',currentOrg.id).order('name'),
    supabase.from('pos_orders').select('*').eq('org_id',currentOrg.id).order('created_at',{ascending:false}).limit(200),
    canManagePayroll?supabase.from('employee_compensation').select('*').eq('org_id',currentOrg.id):Promise.resolve({data:[],error:null}),
    canManagePayroll?supabase.from('payroll_runs').select('*').eq('org_id',currentOrg.id).order('period_month',{ascending:false}).limit(12):Promise.resolve({data:[],error:null}),
    supabase.from('pharmacy_prescriptions').select('*').eq('org_id',currentOrg.id).order('created_at',{ascending:false}).limit(100),
    supabase.from('pharmacy_batches').select('*').eq('org_id',currentOrg.id).order('expiry_date').limit(100),
    supabase.from('salon_appointments').select('*').eq('org_id',currentOrg.id).order('starts_at',{ascending:true}).limit(100),
    supabase.from('salon_services').select('*').eq('org_id',currentOrg.id).order('active',{ascending:false}).order('name'),
    supabase.from('workshop_job_cards').select('*,vehicles(registration_number,make,model)').eq('org_id',currentOrg.id).order('created_at',{ascending:false}).limit(100),
    supabase.from('vehicles').select('*').eq('org_id',currentOrg.id).order('registration_number').limit(100),
    supabase.from('salon_unavailability').select('*').eq('org_id',currentOrg.id).order('starts_at',{ascending:true}).limit(200)
  ]);
  const failed=[settingsResult,dealsResult,invoicesResult,productsResult,employeesResult,projectsResult,customersResult,posOrdersResult,compensationResult,payrollResult,prescriptionsResult,batchesResult,appointmentsResult,servicesResult,jobsResult,vehiclesResult,availabilityResult].find(x=>x.error);
  if(failed)throw failed.error;
  orgSettings=settingsResult.data;
  const initials=(userProfile.full_name||session.user.email).split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  state.deals=dealsResult.data.map(d=>({id:d.id,stage:d.stage,company:d.company,title:d.title,value:Number(d.value),owner:initials,prob:d.probability}));
  state.invoices=invoicesResult.data.map(i=>({id:i.number,dbId:i.id,customer:i.customer,date:new Date(i.issue_date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}),amount:Number(i.total),status:i.status}));
  state.products=productsResult.data.map(p=>({id:p.id,sku:p.sku,barcode:p.barcode,name:p.name,category:p.category||'General',stock:Number(p.stock),forecast:Number(p.forecast),cost:Number(p.cost),price:Number(p.price),reorder:Number(p.reorder_level),taxRate:Number(p.tax_rate||0)}));
  const compensationByEmployee=new Map(compensationResult.data.map(c=>[c.employee_id,c]));
  state.employees=employeesResult.data.map(e=>{const c=compensationByEmployee.get(e.id);return {id:e.id,name:e.name,role:e.role_title||'Team member',dept:e.department||'General',initials:e.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),status:e.employment_status==='active'?'Online':'Offline',employmentStatus:e.employment_status,bookable:Boolean(e.bookable_for_appointments),salary:Number(c?.base_salary||0),payType:c?.pay_type==='hourly'?'Hourly':'Monthly',epfEmployeeRate:Number(c?.epf_employee_rate??8),epfEmployerRate:Number(c?.epf_employer_rate??12),etfRate:Number(c?.etf_rate??3)}});
  state.tasks=projectsResult.data.map(p=>({id:p.id,name:p.name,client:p.client||'Internal',due:p.due_date?new Date(p.due_date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}):'Not set',progress:p.progress,status:p.status}));
  retailCustomers=customersResult.data||[];posRecentOrders=posOrdersResult.data||[];payrollRuns=payrollResult.data||[];
  prescriptions=prescriptionsResult.data||[];salonAppointments=appointmentsResult.data||[];salonAllServices=servicesResult.data||[];salonServices=salonAllServices.filter(service=>service.active!==false);salonAvailability=availabilityResult.data||[];workshopJobs=jobsResult.data||[];vehicles=vehiclesResult.data||[];
  persist();updateChrome();
}

function updateChrome(){
  const workspaceName=currentOrg?.name||'Your workspace';
  const profile=activeBusinessProfile();
  $('.workspace-switcher strong').textContent=workspaceName;
  $('.workspace-switcher small').textContent=`${profile.short} · ${currentMembership?.role||'member'}`;
  const name=userProfile?.full_name||session?.user?.email?.split('@')[0]||'User';
  $('.user-copy strong').textContent=name;
  $('.user-copy small').textContent=userProfile?.platform_role==='super_admin'?'Super administrator':(currentMembership?.role||'Member');
  $('.user-avatar').textContent=name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  $('.workspace-avatar').textContent=workspaceName.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  const enabled=new Set(Array.isArray(orgSettings?.enabled_modules)?orgSettings.enabled_modules:profile.modules);
  $$('.nav-item[data-module]').forEach(item=>item.classList.toggle('module-hidden',!enabled.has(item.dataset.module)));
  const posLabel=$('.nav-item[data-route="pos"] span');if(posLabel)posLabel.textContent=profile===businessProfiles.pharmacy?'Pharmacy POS':profile===businessProfiles.salon?'Client Checkout':profile===businessProfiles.retail_grocery?'Grocery POS':'Point of Sale';
  if(!$('.sync-pill')){const sync=document.createElement('div');sync.className='sync-pill';sync.textContent='Synced with Supabase';document.body.append(sync)}
}

function routeAllowed(route){if(['home','settings'].includes(route))return true;const enabled=Array.isArray(orgSettings?.enabled_modules)?orgSettings.enabled_modules:activeBusinessProfile().modules;return enabled.includes(route)}

async function saveOrgSettings(){
  const orgPatch={};$$('[data-org-field]',page).forEach(el=>orgPatch[el.dataset.orgField]=el.value.trim());
  const settingsPatch={};$$('[data-setting-field]',page).forEach(el=>settingsPatch[el.dataset.settingField]=el.value);
  const preferencePatch={};$$('[data-preference-field]',page).forEach(el=>preferencePatch[el.dataset.preferenceField]=el.dataset.preferenceField==='booking_interval'?Number(el.value):el.value);if(Object.keys(preferencePatch).length){if(preferencePatch.opening_time>=preferencePatch.closing_time)return toast('Closing time must be after opening time');settingsPatch.preferences={...(orgSettings?.preferences||{}),...preferencePatch}}
  if(orgPatch.business_type){orgPatch.industry=orgPatch.business_type;settingsPatch.enabled_modules=(businessProfiles[orgPatch.business_type]||businessProfiles.general_erp).modules}
  const [orgResult,settingsResult]=await Promise.all([
    supabase.from('organizations').update(orgPatch).eq('id',currentOrg.id).select().single(),
    supabase.from('organization_settings').update(settingsPatch).eq('org_id',currentOrg.id).select().single()
  ]);
  if(orgResult.error||settingsResult.error)return toast((orgResult.error||settingsResult.error).message);
  currentOrg=orgResult.data;orgSettings=settingsResult.data;updateChrome();subscribeSalonRealtime();render('settings');toast('Workspace settings saved');
}

function openPrintableDocument(title,body,{pageSize='A4',styles=''}={}){
 const popup=window.open('','_blank');if(!popup){toast('Allow pop-ups to open the printable document');return}popup.opener=null;popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(title)}</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>@page{size:${pageSize};margin:${pageSize==='A4'?'14mm':'4mm'}}*{box-sizing:border-box}body{margin:0;color:#172033;background:#fff;font-family:Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}${styles}</style></head><body>${body}<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),200))<\/script></body></html>`);popup.document.close();
}

function saveClientBooking(record){
 let bookings=[];try{bookings=JSON.parse(localStorage.getItem('hich-salon-bookings')||'[]')}catch{}bookings=[record,...bookings.filter(item=>item.appointment_id!==record.appointment_id)].slice(0,25);localStorage.setItem('hich-salon-bookings',JSON.stringify(bookings));
}

function bookingMessage(record){return `Appointment confirmed\nSalon: ${record.salon}\nService: ${record.service}\nDate & time: ${new Date(record.starts_at).toLocaleString('en-LK',{dateStyle:'full',timeStyle:'short'})}\nCustomer: ${record.customer_name}\nPhone: ${record.customer_phone}${record.staff?`\nSpecialist: ${record.staff}`:''}${Number(record.price)>0?`\nPrice: ${lkr(record.price)}`:''}\nBooking ID: ${record.appointment_id}`}

function printBookingConfirmation(record){
 const rows=[['Booking ID',record.appointment_id],['Customer',record.customer_name],['Phone',record.customer_phone],['Service',record.service],['Date & time',new Date(record.starts_at).toLocaleString('en-LK',{dateStyle:'full',timeStyle:'short'})],['Ends',new Date(record.ends_at).toLocaleTimeString('en-LK',{hour:'numeric',minute:'2-digit'})],['Specialist',record.staff||'To be assigned'],['Price',Number(record.price)>0?lkr(record.price):'Price on request']];const body=`<main class="booking-pdf"><header><div class="mark">H</div><div><small>APPOINTMENT CONFIRMATION</small><h1>${escapeHtml(record.salon)}</h1><p>${escapeHtml(record.salon_address||'')}</p></div><b>CONFIRMED</b></header><section><h2>${escapeHtml(record.service)}</h2><p>${new Date(record.starts_at).toLocaleString('en-LK',{dateStyle:'full',timeStyle:'short'})}</p></section><table>${rows.map(([label,value])=>`<tr><th>${escapeHtml(label)}</th><td>${escapeHtml(value)}</td></tr>`).join('')}</table><footer>Please keep this confirmation and contact ${escapeHtml(record.salon_phone||record.salon)} if you need to change your appointment.</footer></main>`;openPrintableDocument(`Booking ${record.appointment_id}`,body,{styles:'.booking-pdf{max-width:180mm;margin:auto;padding:10mm;border:1px solid #e3dcea}.booking-pdf header{display:grid;grid-template-columns:48px 1fr auto;gap:16px;align-items:center;border-bottom:3px solid #654485;padding-bottom:18px}.mark{width:48px;height:48px;border-radius:13px;background:#654485;color:#fff;display:grid;place-items:center;font-size:25px;font-weight:900}.booking-pdf small{color:#654485;font-weight:800;letter-spacing:.1em}.booking-pdf h1{font-size:24px;margin:5px 0}.booking-pdf p{color:#687086;margin:0}.booking-pdf header>b{color:#18745e;background:#eaf7f2;border-radius:20px;padding:8px 12px;font-size:11px}.booking-pdf section{background:#f6f2f9;padding:20px;margin:22px 0}.booking-pdf section h2{margin:0 0 8px;font-size:20px}.booking-pdf table{width:100%;border-collapse:collapse}.booking-pdf th,.booking-pdf td{padding:11px 8px;border-bottom:1px solid #e7e8ed;text-align:left;font-size:13px}.booking-pdf th{width:34%;color:#6f7688}.booking-pdf footer{margin-top:28px;padding-top:15px;border-top:1px solid #dfe1e7;color:#72798a;font-size:12px;line-height:1.6}'});
}

function showPublicBookingConfirmation(booking,appointment,values){
 const record={...appointment,customer_name:values.customer_name.trim(),customer_phone:values.customer_phone.trim(),customer_email:values.customer_email||'',notes:values.notes||'',saved_at:new Date().toISOString()};saveClientBooking(record);const message=bookingMessage(record);const phone=String(record.salon_phone||'').replace(/\D/g,'').replace(/^0/,'94');booking.innerHTML=`<div class="booking-confirmed"><span>${icon('check')}</span><small>Appointment confirmed & saved</small><h1>You’re booked at ${escapeHtml(record.salon)}</h1><p>${escapeHtml(record.service)} on ${new Date(record.starts_at).toLocaleString('en-LK',{dateStyle:'full',timeStyle:'short'})}</p><div class="booking-confirmation-card"><dl><div><dt>Customer</dt><dd>${escapeHtml(record.customer_name)}</dd></div><div><dt>Phone</dt><dd>${escapeHtml(record.customer_phone)}</dd></div><div><dt>Service</dt><dd>${escapeHtml(record.service)}</dd></div><div><dt>Specialist</dt><dd>${escapeHtml(record.staff||'To be assigned')}</dd></div><div><dt>Booking ID</dt><dd>${escapeHtml(record.appointment_id)}</dd></div></dl><p>This complete booking has been saved on this device.</p><div class="booking-confirmation-actions"><button data-booking-pdf>${icon('download')} Save PDF</button><button class="whatsapp" data-booking-whatsapp>${icon('message')} Send on WhatsApp</button><button class="secondary" data-book-another>Book another</button></div></div></div>`;hydrateIcons(booking);$('[data-booking-pdf]',booking).onclick=()=>printBookingConfirmation(record);$('[data-booking-whatsapp]',booking).onclick=()=>window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank','noopener');$('[data-book-another]',booking).onclick=()=>location.reload();
}

async function showPublicBooking(slug){
 $('#marketingSite').classList.add('hidden');$('#authShell').classList.add('hidden');$('#appShell').classList.add('hidden');$('.sync-pill')?.remove();
 let booking=$('#publicBooking');if(!booking){booking=document.createElement('section');booking.id='publicBooking';booking.className='public-booking';document.body.append(booking)}
 booking.innerHTML='<div class="public-booking-loading"><span class="spinner"></span><p>Opening the appointment book…</p></div>';
 const {data,error}=await supabase.rpc('get_public_salon_booking',{p_slug:slug});
 if(error){booking.innerHTML=`<div class="booking-unavailable"><span class="brand-mark"><i></i><i></i><i></i></span><h1>Booking link unavailable</h1><p>${escapeHtml(error.message)}</p><a href="/">Return to Hich Solutions</a></div>`;return}
 const opening=data.opening_time||'09:00';const closing=data.closing_time||'19:00';const interval=Number(data.booking_interval||30);const [openHour,openMinute]=opening.split(':').map(Number);const [closeHour,closeMinute]=closing.split(':').map(Number);const slots=[];for(let minutes=openHour*60+openMinute;minutes<closeHour*60+closeMinute;minutes+=interval){slots.push(`${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`)}
 const serviceCards=(data.services||[]).map(service=>`<label class="public-service-card"><input type="radio" name="service_id" value="${service.id}" required><span>${icon('calendar')}</span><div><b>${escapeHtml(service.name)}</b><small>${escapeHtml(service.category)} · ${service.duration_minutes} minutes</small>${service.description?`<em>${escapeHtml(service.description)}</em>`:''}</div><strong>${Number(service.price)>0?lkr(service.price):'Price on request'}</strong></label>`).join('');
 const today=new Date();const minDate=new Date(today.getTime()-today.getTimezoneOffset()*60000).toISOString().slice(0,10);const maxDate=new Date(today.getTime()+180*86400000);const maxDateValue=new Date(maxDate.getTime()-maxDate.getTimezoneOffset()*60000).toISOString().slice(0,10);
 booking.innerHTML=`<header class="public-booking-nav"><a class="brand" href="/"><span class="brand-mark"><i></i><i></i><i></i></span><span>Hich Solutions</span></a><span>Secure online booking</span></header><main class="public-booking-main"><section class="booking-intro"><span class="eyebrow">Book online</span><h1>${escapeHtml(data.salon.name)}</h1><p>Choose a service and a convenient time. Your appointment goes directly into the salon calendar.</p><div>${data.salon.address?`<span>${icon('home')} ${escapeHtml(data.salon.address)}</span>`:''}${data.salon.phone?`<span>${icon('message')} ${escapeHtml(data.salon.phone)}</span>`:''}</div></section><form id="publicBookingForm" class="public-booking-form"><div class="booking-step"><span>01</span><div><h2>Choose a service</h2><p>Duration and price come directly from the salon.</p></div></div><div class="public-service-grid">${serviceCards||'<div class="empty-state"><b>Online booking is not open yet</b><p>Please contact the salon directly.</p></div>'}</div><div class="booking-step"><span>02</span><div><h2>Choose date and time</h2><p>Times are shown in Sri Lanka time.</p></div></div><div class="booking-date-grid"><label><span>Date</span><input type="date" name="date" min="${minDate}" max="${maxDateValue}" value="${minDate}" required></label><label><span>Time</span><select name="time" required>${slots.map(slot=>`<option value="${slot}">${new Date(`2000-01-01T${slot}:00`).toLocaleTimeString('en-LK',{hour:'numeric',minute:'2-digit'})}</option>`).join('')}</select></label></div><div class="booking-step"><span>03</span><div><h2>Your details</h2><p>The phone number connects this booking to your client profile and reminders.</p></div></div><div class="booking-client-grid"><label><span>Full name</span><input name="customer_name" autocomplete="name" required></label><label><span>WhatsApp / phone</span><input name="customer_phone" type="tel" autocomplete="tel" placeholder="077 123 4567" required></label><label><span>Email <small>(optional)</small></span><input name="customer_email" type="email" autocomplete="email"></label><label class="wide"><span>Notes <small>(optional)</small></span><textarea name="notes" rows="3" placeholder="Anything the salon should know?"></textarea></label></div><button class="booking-submit" type="submit">Confirm appointment ${icon('calendar')}</button><p class="booking-form-note">Your details are used only to manage this appointment.</p></form></main><footer class="public-booking-footer">Booking powered by Hich Solutions</footer>`;
 hydrateIcons(booking);const form=$('#publicBookingForm',booking);if(!data.services?.length)form.querySelector('[type="submit"]').disabled=true;
 form.onsubmit=async event=>{event.preventDefault();const submit=$('[type="submit"]',form);const values=Object.fromEntries(new FormData(form));if(!values.service_id)return;submit.disabled=true;submit.textContent='Checking availability…';const startsAt=new Date(`${values.date}T${values.time}:00+05:30`).toISOString();const result=await supabase.rpc('book_public_salon_appointment',{p_slug:slug,p_service_id:values.service_id,p_customer_name:values.customer_name,p_customer_phone:values.customer_phone,p_customer_email:values.customer_email||'',p_starts_at:startsAt,p_notes:values.notes||''});if(result.error){submit.disabled=false;submit.innerHTML=`Confirm appointment ${icon('calendar')}`;hydrateIcons(submit);let alert=$('.booking-error',form);if(!alert){alert=document.createElement('div');alert.className='booking-error';form.insertBefore(alert,submit)}alert.textContent=result.error.message;return}showPublicBookingConfirmation(booking,result.data,values)};
}

function showMarketing(){
  $('#marketingSite').classList.remove('hidden');$('#appShell').classList.add('hidden');$('#authShell').classList.add('hidden');$('.sync-pill')?.remove();history.replaceState(null,'',location.pathname);
}
function showAuth(mode='signin'){
  $('#marketingSite').classList.add('hidden');$('#appShell').classList.add('hidden');$('#authShell').classList.remove('hidden');$('#authLoading').classList.add('hidden');$('#authForms').classList.remove('hidden');$('.sync-pill')?.remove();
  const tab=$(`[data-auth-tab="${mode}"]`);if(tab)tab.click();history.replaceState(null,'',`${location.pathname}#${mode}`);
}
function showAuthError(message,{resend=false,info=false}={}){const box=$('#authError');box.textContent=message;box.classList.toggle('hidden',!message);box.classList.toggle('info',info);$('#resendConfirmation').classList.toggle('hidden',!resend)}
function authRedirectUrl(){return `${location.origin}/`}
function readAuthCallbackError(){
  const params=new URLSearchParams(location.hash.replace(/^#/,''));
  const code=params.get('error_code');
  if(!code)return null;
  const description=(params.get('error_description')||'Authentication failed.').replace(/\+/g,' ');
  history.replaceState(null,'',location.pathname+location.search);
  return {code,description};
}
async function bootstrapApp(activeSession){
  if(bootstrapPromise)return bootstrapPromise;session=activeSession;bootstrapPromise=(async()=>{$('#marketingSite').classList.add('hidden');$('#authShell').classList.remove('hidden');$('#authLoading').classList.remove('hidden');$('#authForms').classList.add('hidden');let lastError;for(let attempt=0;attempt<2;attempt++){try{await loadWorkspaceData();lastError=null;break}catch(error){lastError=error;if(attempt===0)await new Promise(resolve=>setTimeout(resolve,350))}}if(lastError)throw lastError;$('#marketingSite').classList.add('hidden');$('#authShell').classList.add('hidden');$('#appShell').classList.remove('hidden');hydrateIcons();subscribeSalonRealtime();if(!orgSettings?.preferences?.onboarding_completed){showOnboarding();return}$('#appShell').classList.remove('onboarding-active');const initial=location.hash.slice(1);render(renderers[initial]?initial:'home')})().catch(error=>{showAuth();showAuthError(error.message||'Unable to load your workspace.')}).finally(()=>{bootstrapPromise=null});return bootstrapPromise;
}
function subscribeSalonRealtime(){
 if(salonRealtimeChannel){supabase.removeChannel(salonRealtimeChannel);salonRealtimeChannel=null}if(!currentOrg?.id||activeBusinessProfile()!==businessProfiles.salon)return;salonRealtimeChannel=supabase.channel(`salon-workspace-${currentOrg.id}`).on('postgres_changes',{event:'*',schema:'public',table:'salon_appointments',filter:`org_id=eq.${currentOrg.id}`},()=>{setTimeout(async()=>{if(!session)return;try{await loadWorkspaceData();if(['salon','reminders'].includes(currentRoute))render(currentRoute);else toast('A salon booking was updated in real time')}catch{}},120)}).on('postgres_changes',{event:'*',schema:'public',table:'salon_unavailability',filter:`org_id=eq.${currentOrg.id}`},()=>{setTimeout(async()=>{if(!session)return;try{await loadWorkspaceData();if(['salon','settings'].includes(currentRoute))render(currentRoute)}catch{}},120)}).subscribe();
}
async function initAuth(){
  const bookingMatch=location.pathname.match(/^\/book\/([^/]+)\/?$/);if(bookingMatch){await showPublicBooking(decodeURIComponent(bookingMatch[1]));return}
  const callbackError=readAuthCallbackError();
  const {data,error}=await supabase.auth.getSession();
  if(error){showAuth();showAuthError(error.message);return}
  session=data.session;
  const requested=location.hash.slice(1);
  if(requested==='login'||requested==='signin')showAuth('signin');else if(requested==='signup')showAuth('signup');else if(data.session)await bootstrapApp(data.session);else showMarketing();
  if(callbackError){showAuth('signin');showAuthError(callbackError.description)}
  supabase.auth.onAuthStateChange((event,nextSession)=>{if(event==='SIGNED_OUT'){session=null;if(salonRealtimeChannel){supabase.removeChannel(salonRealtimeChannel);salonRealtimeChannel=null}showMarketing();return}if(nextSession)session=nextSession;if(event==='SIGNED_IN'&&nextSession&&$('#appShell').classList.contains('hidden')&&!['signin','signup','login'].includes(location.hash.slice(1)))setTimeout(()=>bootstrapApp(nextSession),0)});
}
function openProfile(){
  const layer=$('#modalLayer');layer.innerHTML=`<div class="modal-backdrop" data-close-modal></div><section class="modal search-modal"><div class="modal-body"><span class="eyebrow">Account</span><h2 style="font:800 1.3rem Manrope;margin:7px 0">${userProfile?.full_name||'Your profile'}</h2><p style="font-size:.72rem;color:var(--muted)">${session?.user?.email||''}</p><div class="alert-row" style="margin:20px 0"><span class="record-icon">${currentMembership?.role?.slice(0,1).toUpperCase()||'M'}</span><div><strong>${currentOrg?.name||'Workspace'}</strong><small>${currentMembership?.role||'member'} · ${userProfile?.platform_role==='super_admin'?'Platform super admin':'Workspace user'}</small></div></div><div class="modal-actions"><button class="btn" data-close-modal>Close</button><button class="btn primary" id="signOutButton">Sign out</button></div></div></section>`;layer.classList.add('open');layer.setAttribute('aria-hidden','false');$$('[data-close-modal]',layer).forEach(x=>x.onclick=closeModal);$('#signOutButton').onclick=async()=>{await supabase.auth.signOut();closeModal()};
}

