$('#signinForm').onsubmit=async event=>{event.preventDefault();showAuthError('');const button=$('[type="submit"]',event.currentTarget);button.disabled=true;button.textContent='Signing in…';const values=Object.fromEntries(new FormData(event.currentTarget));const {data,error}=await supabase.auth.signInWithPassword({email:values.email,password:values.password});button.disabled=false;button.textContent='Sign in';if(error)return showAuthError(error.message);await bootstrapApp(data.session)};
$('#signupForm').onsubmit=async event=>{event.preventDefault();showAuthError('');const button=$('[type="submit"]',event.currentTarget);button.disabled=true;button.textContent='Creating account…';const values=Object.fromEntries(new FormData(event.currentTarget));let response;let result;try{response=await fetch('/api/signup',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(values)});result=await response.json()}catch{button.disabled=false;button.textContent='Create account & continue';return showAuthError('The account service is unavailable. Start the app with npm run dev.')}if(!response.ok){button.disabled=false;button.textContent='Create account & continue';return showAuthError(result.error||'Unable to create account.')}const login=await supabase.auth.signInWithPassword({email:values.email,password:values.password});button.disabled=false;button.textContent='Create account & continue';if(login.error)return showAuthError(login.error.message);await bootstrapApp(login.data.session)};
